param([Parameter(Mandatory)][string]$OutputPath,[string]$PlanPath=(Join-Path $PSScriptRoot 'type-load-exception-getter-profile-plan-v1.json'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
[Globalization.CultureInfo]::CurrentCulture=[Globalization.CultureInfo]::InvariantCulture;[Globalization.CultureInfo]::CurrentUICulture=[Globalization.CultureInfo]::InvariantCulture
$plan=Get-Content -LiteralPath $PlanPath -Raw|ConvertFrom-Json;$nullMessageControls=0;$messageField=[Exception].GetField('_message',[Reflection.BindingFlags]'Instance,NonPublic');$c0=[TypeLoadException].GetConstructor([type[]]@());$c1=[TypeLoadException].GetConstructor([type[]]@([string]));$c2=[TypeLoadException].GetConstructor([type[]]@([string],[Exception]));$constructors=[Collections.Generic.List[object]]::new();$lookups=[Collections.Generic.List[object]]::new()
for($index=0;$index -lt $plan.constructors.Count;$index++){$spec=$plan.constructors[$index];$message=$null;if($null -ne $plan.messages[$spec.messageIndex]){$message=[string]::new([char[]]([int[]]$plan.messages[$spec.messageIndex]))};$inner=$null;if($spec.inner -eq 'plain'){$inner=[Exception]::new()}elseif($spec.inner -eq 'named'){$inner=[Exception]::new('inner')};$e=switch($spec.route){'default'{$c0.Invoke([object[]]@())};'message'{$arguments=[object[]]::new(1);$arguments[0]=$message;$c1.Invoke($arguments)};'inner'{$arguments=[object[]]::new(2);$arguments[0]=$message;$arguments[1]=$inner;$c2.Invoke($arguments)}};if($spec.route -ne 'default' -and $null -eq $message){if($null -ne $messageField.GetValue($e)){throw 'Null message was coerced before native construction'};$nullMessageControls++};$constructors.Add([ordered]@{index=$index;messageUnits=[int[]][char[]]$e.Message;typeNameUnits=[int[]][char[]]$e.TypeName;hResult=$e.HResult;innerSame=[object]::ReferenceEquals($e.InnerException,$inner)})}
foreach($name in $plan.names){foreach($ignore in $plan.ignoreCase){try{$null=[type]::GetType($name,$true,[bool]$ignore);throw 'Expected missing lookup'}catch{$e=$_.Exception;while($e -is [Reflection.TargetInvocationException] -or $e -is [Management.Automation.MethodInvocationException]){$e=$e.InnerException};if($e -isnot [TypeLoadException]){throw};$lookups.Add([ordered]@{name=$name;ignoreCase=[bool]$ignore;exception=$e.GetType().FullName;typeNameUnits=[int[]][char[]]$e.TypeName;hResult=$e.HResult;observedMessageUnits=[int[]][char[]]$e.Message})}}}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();planSha256=(Get-FileHash -LiteralPath $PlanPath -Algorithm SHA256).Hash.ToLowerInvariant();culture='Invariant';nullMessageControls=$nullMessageControls;constructors=$constructors.ToArray();lookups=$lookups.ToArray();qualification=$plan.qualification};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 18 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS TypeLoadException getters: $($constructors.Count) constructors and $($lookups.Count) missing lookups"
